# Hypothesis: Find connected components per color, reflect them as wholes

from collections import deque

def get_connected_components(grid, color):
    """Find all connected (4-neighbor) regions of specified color"""
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False]*cols for _ in range(rows)]
    components = []

    def bfs(start_r, start_c):
        comp = []
        queue = deque([(start_r, start_c)])
        visited[start_r][start_c] = True

        while queue:
            r, c = queue.popleft()
            comp.append((r, c))

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == color:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

        return comp

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and not visited[r][c]:
                comp = bfs(r, c)
                if comp:
                    components.append(comp)

    return components

# Check test input connected components
