# Now, what would reflecting these COMPONENTS as wholes produce?
def reflect_component_components(grid, bg):
    """Reflect each connected component across vertical axis"""
    rows = len(grid)
    cols = len(grid[0])

    # Get all components (combine all non-bg colors into one mask first)
    result = [[bg]*cols for _ in range(rows)]

    # Copy original
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                result[r][c] = grid[r][c]

    # For each connected component of non-bg, add its mirror
    visited = [[False]*cols for _ in range(rows)]

    def bfs(start_r, start_c):
        comp = []
        queue = deque([(start_r, start_c)])
        visited[start_r][start_c] = True

        while queue:
            r, c = queue.popleft()
            comp.append((r, c))

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] != bg:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

        return comp

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and not visited[r][c]:
                comp = bfs(r, c)

                # Keep track of original vs mirror positions
                orig_positions = set(comp)
                mirror_positions = set()
                for pr, pc in comp:
                    mir_c = cols - 1 - pc
                    mirror_positions.add((pr, mir_c))

                # For each position in mirror, copy the color from the corresponding original
                for mr, mc in mirror_positions:
                    # Find where this mirrors FROM in original
                    orig_mir_c = cols - 1 - mc
                    orig_val = grid[mr][orig_mir_c]
                    if orig_val != bg:
                        result[mr][mc] = orig_val

    return result

