# Fix: skip background color in expansion
def test_expansion_by_color(grid):
    bg = 8
    rows = len(grid)
    cols = len(grid[0])

    result = [[bg]*cols for _ in range(rows)]

    # First copy everything (non-bg)
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != bg:
                result[r][c] = val

    # Expand each foreground color before mirroring
    expansion = {'0': 1, '3': 1}

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                continue

            expand_left = expansion.get(str(val), 0)
            expand_right = expansion.get(str(val), 0)

            for dc in range(1, expand_right + 1):
                nc = c + dc
                if nc < cols and result[r][nc] == bg:
                    result[r][nc] = int(val)

            for dc in range(1, expand_left + 1):
                nc = c - dc
                if nc >= 0 and result[r][nc] == bg:
                    result[r][nc] = int(val)

    # Global reflection of all non-bg
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != bg:
                mir_c = cols - 1 - c
                if mir_c != c:
                    result[r][mir_c] = val

    return result

