# Hypothesis: Each foreground color EXPANDS by some amount BEFORE mirroring
# e.g., 0 expands by +1 cell left/right, 3 expands by +2 cells

def test_color_expansion_before_mirror(grid):
    """Expand each color outward before applying global mirror"""
    bg = 8
    cols = len(grid[0])

    # Expansion amounts for each color
    expansion = {0: 1, 3: 2}  # Try different amounts

    result = [[bg]*cols for _ in range(len(grid))]

    for r in range(len(grid)):
        # First, expand each pixel to fill its neighborhood
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                continue

            expand = expansion[val]

            # Fill cells within expansion distance
            for dc in range(-expand, expand + 1):
                nc = c + dc
                if 0 <= nc < cols and result[r][nc] == bg:
                    result[r][nc] = val

        # Then do global mirror on expanded version
        for c in range(cols):
            val = result[r][c]
            if val != bg:
                mir_c = cols - 1 - c
                if mir_c != c and result[r][mir_c] == bg:
                    result[r][mir_c] = val

    return result

